            channel: number;
            /** @description Whether rule is enabled. */
            enabled?: boolean;
            tier?: components["schemas"]["LocationTier"];
            /** @description Update interval in seconds for this target, paced independently of every other target. Floored at 30. */
            interval_s?: number;
